// Generated by `factory render`. Do not edit.
// What a commercial scanner adds to a finding, shared by the engine and the generated CI script (copied next to it:
// Node's own modules only). Everything here is data-driven: the definitions in packs/commercial/analysis.json say how a
// vendor's severities map to the factory's (blocking | major | minor), the client may override the map
// (analysis.commercial.severity), and the vendor's own triage state of a finding is respected and reported, never set.
//
//   severityOf(tool, finding)  -> 'blocking' | 'major' | 'minor'
//   triageOf(finding)          -> null (open) | 'accepted' | 'false-positive' | 'suppressed' | 'fixed'
//   dedupe(findings)           -> findings with one entry per location + CWE (the others listed in `alsoBy`)
//   cweOf(tags...)             -> 'CWE-89' | null
//   expandSecretEnv(env, vars) -> the env with `${NAME}` references read from the environment (never logged)

export const SEVERITIES = ['blocking', 'major', 'minor'];
export const VENDOR_SEVERITIES = ['critical', 'high', 'medium', 'low', 'info'];
// Triage states that take a finding out of the blocking set: a person decided it in the vendor's system.
export const CLOSED_TRIAGE = ['accepted', 'false-positive', 'suppressed', 'fixed'];

// A vendor's word for severity, normalised. Numbers are CVSS-like scores (GitHub's security-severity, Snyk's
// security-severity) or Veracode's 0-5 scale when `scale: 5`.
export function normalizeVendorSeverity(value, { scale = 10 } = {}) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number' || /^\d+(\.\d+)?$/.test(String(value))) {
    const n = Number(value);
    if (scale === 5) return n >= 5 ? 'critical' : n >= 4 ? 'high' : n >= 3 ? 'medium' : n >= 2 ? 'low' : 'info';
    return n >= 9 ? 'critical' : n >= 7 ? 'high' : n >= 4 ? 'medium' : n > 0 ? 'low' : 'info';
  }
  const s = String(value).toLowerCase().replace(/[\s_-]+/g, '');
  if (['critical', 'blocker', 'veryhigh'].includes(s)) return 'critical';
  if (['high', 'major', 'severe'].includes(s)) return 'high';
  if (['medium', 'moderate', 'warning'].includes(s)) return 'medium';
  if (['low', 'minor', 'note', 'verylow'].includes(s)) return 'low';
  if (['info', 'informational', 'none', 'trivial'].includes(s)) return 'info';
  if (s === 'error') return 'high';
  return null;
}

// The severity a finding gets in the factory. A tool with a severity map (every commercial definition) maps the
// finding's vendor severity, else its SARIF level; a tool without one keeps the open-source behaviour (its block list
// says what blocks, everything else is minor).
export function severityOf(tool, f) {
  const map = tool.severity;
  if (map && typeof map === 'object') {
    const vendor = f.vendorSeverity ?? normalizeVendorSeverity(f.level === 'error' ? 'high' : f.level === 'warning' ? 'medium' : 'low');
    const mapped = map[vendor] ?? map.default;
    if (SEVERITIES.includes(mapped)) return mapped;
  }
  const levels = tool.block?.levels ?? [];
  const rules = tool.block?.rules ?? [];
  const blocks = levels.includes(f.level) || rules.some((r) => (r.endsWith('*') ? String(f.rule ?? '').startsWith(r.slice(0, -1)) : r === f.rule));
  return blocks ? 'blocking' : 'minor';
}

// SARIF suppressions (2.1.0 §3.35): a suppression without a status, or with status "accepted", is in force; "underReview"
// and "rejected" leave the finding open. The vendor's own words (justification) are kept for the report.
export function sarifTriage(result) {
  const s = (result?.suppressions ?? []).find((x) => x && (x.status === undefined || x.status === 'accepted'));
  if (!s) return null;
  const why = String(s.justification ?? '').toLowerCase();
  return { state: /false.?positive/.test(why) ? 'false-positive' : s.kind === 'external' ? 'accepted' : 'suppressed', by: s.kind ?? 'external', justification: s.justification ?? null };
}

export const triageOf = (f) => (f?.triage && CLOSED_TRIAGE.includes(f.triage.state ?? f.triage) ? f.triage.state ?? f.triage : null);

const CWE = /\bcwe[-_/: ]?(\d{1,5})\b/i;
export function cweOf(...values) {
  for (const v of values.flat(Infinity)) {
    if (v === null || v === undefined) continue;
    if (typeof v === 'number') return `CWE-${v}`;
    const m = String(v).match(CWE);
    if (m) return `CWE-${Number(m[1])}`;
  }
  return null;
}

const RANK = { blocking: 0, major: 1, minor: 2 };
// One finding per (file, line, CWE): a commercial scanner beside the open-source tools reports the same weakness at the
// same place once, at the higher severity, with the other tools named. Findings without a CWE or a line are kept as
// they are (nothing says they are the same).
export function dedupe(findings) {
  const out = [];
  const seen = new Map();
  for (const f of findings) {
    if (!f.cwe || !f.file || !f.line) {
      out.push(f);
      continue;
    }
    const k = `${f.file}:${f.line}:${f.cwe}`;
    const i = seen.get(k);
    if (i === undefined) {
      seen.set(k, out.length);
      out.push(f);
      continue;
    }
    const had = out[i];
    const [keep, drop] = (RANK[f.severity] ?? 3) < (RANK[had.severity] ?? 3) ? [f, had] : [had, f];
    out[i] = { ...keep, alsoBy: [...new Set([...(keep.alsoBy ?? []), drop.tool, ...(drop.alsoBy ?? [])].filter(Boolean))] };
  }
  return out;
}

// `${NAME}` references in a tool's env, read from the environment when the tool runs. A reference whose variable is
// not set is returned in `missing` (the tool does not run: a scanner without its token cannot give an answer, and the
// job fails closed). Values never leave the env object.
export function expandSecretEnv(env = {}, source = process.env) {
  const out = {};
  const missing = [];
  for (const [k, v] of Object.entries(env ?? {})) {
    out[k] = String(v).replace(/\$\{([A-Za-z_][A-Za-z0-9_]*)\}/g, (_, name) => {
      if (source[name] === undefined || source[name] === '') {
        missing.push(name);
        return '';
      }
      return source[name];
    });
  }
  return { env: out, missing: [...new Set(missing)] };
}
